test_ranges={'home':(44,56),'quotes':(242,253),'customers':(31,46),'showcase':(12,34),'production':(50,62),'shipments':(40,55),'installations':(50,68),'orders':(59,73),'productionDashboard':(61,69),'salesDashboard':(40,46),'engineeringDashboard':(87,102),'engineering':(68,79),'warehouseDashboard':(83,104),'warehouse':(99,106),'modules':(179,188),'structures':(60,77),'components':(52,68),'materials':(38,68),'edges':(36,45),'hardware':(48,64),'finishes':(43,56),'settings':(26,55),'devices':(38,80),'security':(36,92),'users':(36,49),'platform':(27,61)}
tests=list((s/'packages/ui').rglob('*.test.*'))
def evidence(file,a,b,kind):
 ls=(s/file).read_text().splitlines();assert 0<a<=b<=len(ls),(file,a,b);return {'file':file,'startLine':a,'endLine':b,'excerpt':'\n'.join(ls[a-1:b]),'sha256':hashlib.sha256((s/file).read_bytes()).hexdigest(),'kind':kind}
out=[]
for x in inv['screens']:
 key=x['id'][4:];a,b,actual,own,test=rows[key];ev=[evidence(x['file'],a,b,'SOURCE_SEMANTIC_FRAGMENT')];tfiles=[p for p in tests if p.name.startswith(Path(x['file']).stem+'.')];te=[]
 if key in test_ranges:
  ta,tb=test_ranges[key];assert tfiles;te=[evidence(str(tfiles[0].relative_to(s)),ta,tb,'TEST_BODY_INSPECTED_NOT_EXECUTED')]
 out.append({'id':x['id'],'name':x['name'],'route':x['route'],'file':x['file'],'status':'PARTIAL','auditDepth':'BOUNDED_SCREEN_SEMANTIC_REVIEW','runtimeStatus':'UNKNOWN_IN_THIS_SUPPLEMENT','actualBehavior':actual,'ownershipBoundary':own,'testCoverage':{'claim':test,'boundary':'Specific body inspected, not full suite review; no tests executed. Mock callback/fetch and source guards do not prove real backend behavior.','evidence':te},'evidence':ev,'nextProof':'Verify this screen with authorized and denied roles, real backend success/failure, loading/empty separation, keyboard/focus, 390/768/1280 layout and persistence after reload. '+own,'visualDimensions':{'accessibility':'UNKNOWN computed contrast/focus; source semantics only','performance':'UNKNOWN profiling','responsive':'UNKNOWN in this supplement; retain existing root browser evidence','theming':'Existing design system retained; per-element computed coverage UNKNOWN','antiPatterns':'UNKNOWN visual verdict; no invented score'}})
# Every secondary surface remains accounted for; exact-file overlap is context linkage, never semantic certification.
links=[]
for x in inv['secondaryInterfaces']:
 matches=[a['id'] for a in out if a['file']==x['file']];links.append({'id':x['id'],'file':x['file'],'screenContextIds':matches,'mappingBasis':'Exact source-file overlap' if matches else 'No exact primary-screen file overlap','auditDepth':'PENDING_SURFACE_SEMANTIC_REVIEW','boundary':'Screen context does not certify this exported component; caller, state/action and interaction proof remain required.'})
inline=[]
for i,x in enumerate(inv['inlineSurfaces'],1):
 matches=[a['id'] for a in out if a['file']==x['file']];inline.append({'id':f'WEB-INLINE-{i:03d}','file':x['file'],'screenContextIds':matches,'auditDepth':'PENDING_INLINE_INTERACTION_REVIEW','boundary':'Occurrences retained in web-inventory.json; no inferred modal/form acceptance from parent screen review.'})
d={'sourceCommit':inv['sourceCommit'],'method':'Manual reading and interpretation of named control-flow/test bodies at pinned source; report-only. No browser/API/DB/test execution. Per-screen fragments do not certify every child.','screens':out,'secondarySurfaceMappings':links,'inlineSurfaceMappings':inline,'findings':[],'existingFindingLinks':[{'findingId':'WEB-01','screenIds':['WEB-warehouse','WEB-warehouseDashboard']},{'findingId':'WEB-02','screenIds':['WEB-users']},{'findingId':'FM-05','screenIds':['WEB-modules','WEB-components','WEB-quotes'],'basis':'Potential authoring context; exact mounted component scope in feature-matrix.json'}],'coverage':{'primaryScreens':len(out),'semanticScreenFragments':len(out),'runtimeCertifiedScreens':0,'testBodiesInspected':sum(bool(x['testCoverage']['evidence']) for x in out),'secondarySurfacesAccounted':len(links),'secondaryExactFileContextLinks':sum(bool(x['screenContextIds']) for x in links),'secondarySemanticallyCertified':0,'inlineFilesAccounted':len(inline),'inlineExactFileContextLinks':sum(bool(x['screenContextIds']) for x in inline),'inlineSemanticallyCertified':0}}
(r/'data/web-semantic-audit.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
md=['# Web screen semantic supplement','', '29 named screen fragments reviewed; no full-screen/runtime certification. Secondary surfaces (259) and inline files (140) remain explicitly pending, with exact-file context links where available. No visual health score is fabricated.','']
for x in out:md += [f"## {x['id']} — {x['name']}",x['actualBehavior'],'',x['ownershipBoundary'],'',f"Test scope: {x['testCoverage']['claim']}. Body inspection only; no execution.",'',f"Evidence: `{x['file']}:{x['evidence'][0]['startLine']}-{x['evidence'][0]['endLine']}`",'']
(r/'evidence/web-semantic-audit.md').write_text('\n'.join(md)+'\n');print(d['coverage'])
